# ══════════════════════════════════════════════════════════════════════════
# BUG 1 — TTS race: concurrent speakers truncated each other and opened the
# mic mid-reply, causing a self-hearing feedback loop.
# ══════════════════════════════════════════════════════════════════════════

def test_tts_concurrency() -> None:
    section("BUG 1 — TTS concurrency (truncation + feedback loop)")

    from voice.text_to_speech import TextToSpeech
    from voice import speaking_state

    class FakeTTS(TextToSpeech):
        """Same machinery, silent + fast: no real `say` subprocess."""
        def _say(self, text: str) -> None:
            self.log.append(("start", text))
            time.sleep(0.05)
            self.log.append(("end", text))

    tts = FakeTTS()
    tts.log = []

    threads = [threading.Thread(target=tts.speak, args=(f"line {i}",)) for i in range(6)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()

    starts = sum(1 for e in tts.log if e[0] == "start")
    ends = sum(1 for e in tts.log if e[0] == "end")
    check("all utterances complete (none truncated)", starts == 6 and ends == 6,
          f"started={starts} ended={ends}")

    paired = all(
        tts.log[i][0] == "start" and tts.log[i + 1][0] == "end"
        and tts.log[i][1] == tts.log[i + 1][1]
        for i in range(0, len(tts.log), 2)
    )
    check("utterances never interleave", paired)

    # Mic must stay shut for the whole burst, not flicker open between lines.
    tts2 = FakeTTS()
    tts2.log = []
    seen: list[bool] = []

    def watch() -> None:
        for _ in range(40):
            seen.append(speaking_state.is_speaking())
            time.sleep(0.01)

    w = threading.Thread(target=watch)
    w.start()
    for i in range(4):
        tts2.speak_async(f"s{i}")
    w.join()
    tts2._queue.join()

    if True in seen:
        first = seen.index(True)
        last = len(seen) - 1 - seen[::-1].index(True)
        gaps = seen[first:last].count(False)
    else:
        gaps = -1
    check("mic never reopens mid-reply", gaps == 0, f"gaps={gaps}")

    tts.shutdown()
    tts2.shutdown()
    check("worker thread joins on shutdown", not tts._worker.is_alive())


# ══════════════════════════════════════════════════════════════════════════
# BUG 2 — Memory store: deprecated utcnow, UTC-vs-local day boundary,
# FTS5 operator injection.
# ══════════════════════════════════════════════════════════════════════════

def test_memory_store() -> None:
    section("BUG 2 — Memory store (timezone + FTS5)")

    from memory.store import MemoryStore, _fts_query, _utc_now_iso

    db = tempfile.mktemp(suffix=".db")
    m = MemoryStore(db)
    try:
        m.remember("aki likes coffee")
        m.remember("deploy jarvis on friday")

        # FTS5 used to raise `fts5: syntax error` on bare uppercase operators.
        # Reachable because the LLM classifier returns entities uncased.
        crashed = []
        for q in ["AND", "OR", "NOT", "NEAR", "Aki OR coffee", '"quoted"', "a AND b"]:
            try:
                m.recall(q)
            except Exception as e:
                crashed.append((q, str(e)))
        check("FTS5 operators do not crash recall", not crashed, str(crashed[:2]))

        check("recall still finds real matches", len(m.recall("coffee")) == 1)
        check("_fts_query quotes every token", _fts_query("a OR b") == '"a" OR "OR" OR "b"',
              _fts_query("a OR b"))

        # Stored timestamps must be naive-UTC ISO, matching legacy rows.
        ts = _utc_now_iso()
        check("timestamp has no tz suffix (format stable)", "+" not in ts and "Z" not in ts, ts)

        # today_events must use LOCAL midnight. At UTC+5:30 the old code
        # treated 05:30 local as the day's start.
        m.log_event("hi", "hello", "test")
        check("today_events sees an event logged now", len(m.today_events()) >= 1)

        local_midnight = datetime.now().astimezone().replace(
            hour=0, minute=0, second=0, microsecond=0
        )
        as_utc = local_midnight.astimezone(timezone.utc).replace(tzinfo=None)
        offset_h = (local_midnight.utcoffset().total_seconds() / 3600) if local_midnight.utcoffset() else 0
        check("local midnight converts to a different UTC instant when TZ != UTC",
              (as_utc.hour != 0) == (offset_h != 0),
              f"local={local_midnight} utc={as_utc} offset={offset_h}")
    finally:
        m.close()
        if os.path.exists(db):
            os.unlink(db)


