# BUG 4 — AppleScript: no timeout (worker-pool starvation) + injection.
# ══════════════════════════════════════════════════════════════════════════

def test_applescript() -> None:
    section("BUG 4 — AppleScript timeout + injection")

    from integrations.macos import apple_script as a

    check("quotes escaped", a._q('say "hi"') == '"say \\"hi\\""', a._q('say "hi"'))
    check("backslashes escaped first", a._q("a\\b") == '"a\\\\b"', a._q("a\\b"))

    payload = 'Finder" to get name of every process --'
    script = f"tell application {a._q(payload)} to activate"
    # After escaping there must be exactly one unescaped quote pair.
    unescaped = script.replace('\\"', "")
    check("injection payload cannot break out of the literal",
          unescaped.count('"') == 2, script)

    if sys.platform == "darwin":
        t0 = time.time()
        ok, out = a.run("delay 30", timeout=2)
        elapsed = time.time() - t0
        check("osascript timeout is enforced", (not ok) and elapsed < 5,
              f"ok={ok} elapsed={elapsed:.1f}s")
    else:
        check("osascript timeout (skipped: not macOS)", True)


