# BUG 6 — Module hygiene: importable names, no stale (C)-prefixed modules.
# ══════════════════════════════════════════════════════════════════════════

def test_imports() -> None:
    section("BUG 6 — Module import hygiene")

    import importlib
    mods = [
        "core.assistant", "core.command_router", "utils.latency_profiler",
        "utils.helpers", "config.user_config", "memory.store",
        "voice.text_to_speech", "integrations.macos.apple_script",
        "skills.wikipedia_lookup", "skills.jokes", "skills.system_stats",
        "skills.define_word", "skills.news_headlines", "skills.coding_assistant",
    ]
    broken = []
    for mod in mods:
        try:
            importlib.import_module(mod)
        except Exception as e:
            broken.append(f"{mod}: {type(e).__name__}")
    check("all modules import", not broken, "; ".join(broken))

    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    stale = []
    for dirpath, dirnames, filenames in os.walk(root):
        if "node_modules" in dirpath or "/.git" in dirpath or "/desktop" in dirpath:
            continue
        stale += [f for f in filenames if f.startswith("(C)") and f.endswith(".py")]
    check("no (C)-prefixed python modules (unimportable)", not stale, str(stale))


