# BUG 7 — Local intent model must abstain rather than guess, and must never
# degrade routing that the regex registry already handles.
# ══════════════════════════════════════════════════════════════════════════

def test_local_intent_model() -> None:
    section("BUG 7 — Local intent model (gating + safety)")

    from ai.intent_classifier_local import get_local_classifier

    clf = get_local_classifier()
    if not clf.available:
        check("model present (skipped: not trained)", True)
        return

    check("confidence gate is meaningful", 0.5 <= clf.threshold <= 0.99,
          f"threshold={clf.threshold}")

    # Nonsense must not clear the gate — abstaining is the whole design.
    junk = ["asdf qwer zxcv", "blorp fnord", "aaaaaaa", "xyzzy plugh"]
    confident_junk = [j for j in junk if clf.predict_gated(j)[0] is not None]
    check("abstains on nonsense", not confident_junk, f"answered: {confident_junk}")

    # Clear commands should be handled locally and correctly.
    clear = [
        ("bring up spotify", "open_app"),
        ("crack me up", "jokes"),
        ("how much power is left", "battery"),
        ("catch me up on whats going on", "news_headlines"),
    ]
    wrong = []
    for text, want in clear:
        got, conf = clf.predict_gated(text)
        if got != want:
            wrong.append(f"{text!r}: {got}({conf:.2f}) != {want}")
    check("unambiguous phrasings route locally", not wrong, "; ".join(wrong))

    # The model must never override a confident regex match.
    from skills._registry import get_registry
    reg = get_registry()
    overridden = []
    for text, want in [("volume 50", "volume"), ("take a screenshot", "screenshot"),
                       ("what time is it", "time_date"), ("open spotify", "open_app")]:
        skill, m = reg.match(text)
        if reg.is_high_confidence(m) and skill.name != want:
            overridden.append(text)
    check("regex tier still wins on exact commands", not overridden, str(overridden))

    # Inference must stay fast enough to be worth having.
    t0 = time.perf_counter()
    for _ in range(50):
        clf.predict("bring up spotify")
    per_call_ms = (time.perf_counter() - t0) / 50 * 1000
    check("inference under 10ms", per_call_ms < 10, f"{per_call_ms:.2f}ms")


