# FEATURE — routing provenance + feedback loop.
# ══════════════════════════════════════════════════════════════════════════

def test_feedback_loop() -> None:
    section("FEATURE — feedback loop (provenance + trustworthy labels)")

    import sqlite3
    from memory.store import MemoryStore

    db = tempfile.mktemp(suffix=".db")
    m = MemoryStore(db)
    try:
        m.log_event("volume 50", "ok", "volume", source="regex", confidence=0.95)
        m.log_event("crank it", "ok", "volume", source="local", confidence=0.88)
        m.log_event("do the thing", "ok", "conversation", source="llm", confidence=0.6)
        m.log_event("low conf", "ok", "volume", source="regex", confidence=0.4)

        trainable = m.training_events()
        check("only high-confidence regex rows are trainable",
              trainable == [("volume 50", "volume")], str(trainable))
        check("model predictions are excluded from labels",
              all(t[0] not in ("crank it", "do the thing") for t in trainable))
        check("all events still recorded", len(m.recent_events()) == 4)
    finally:
        m.close()
        if os.path.exists(db):
            os.unlink(db)

    # Migration: a pre-existing DB must gain the new columns without data loss.
    legacy = tempfile.mktemp(suffix=".db")
    conn = sqlite3.connect(legacy)
    conn.executescript(
        "CREATE TABLE events (id INTEGER PRIMARY KEY AUTOINCREMENT, "
        "user_text TEXT NOT NULL, reply_text TEXT NOT NULL, "
        "skill TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);"
    )
    conn.execute(
        "INSERT INTO events (user_text, reply_text, skill, created_at) "
        "VALUES ('old', 'row', 'volume', '2026-01-01T00:00:00')"
    )
    conn.commit()
    conn.close()

    m2 = MemoryStore(legacy)
    try:
        cols = {r["name"] for r in m2._conn.execute("PRAGMA table_info(events)").fetchall()}
        check("migration adds source/confidence", {"source", "confidence"} <= cols, str(cols))
        check("migration preserves existing rows", len(m2.recent_events()) == 1)
    finally:
        m2.close()
        if os.path.exists(legacy):
            os.unlink(legacy)

    from ai.intent_augment import _load_feedback, build_augmented
    fb = _load_feedback()
    if fb:
        data = build_augmented()
        missing = [
            (s, u) for s, utts in fb.items() for u in utts
            if u.strip().lower() not in data.get(s, [])
        ]
        check("collected feedback reaches the training set", not missing, str(missing[:3]))
    else:
        check("feedback file absent is handled (fresh install)", True)


