# FEATURE — live voice state published for the HUD.
# ══════════════════════════════════════════════════════════════════════════

def test_voice_state() -> None:
    section("FEATURE — live voice state channel")

    import json
    from core import voice_state

    original = voice_state.get_state()
    try:
        seen = []
        for st in (voice_state.IDLE, voice_state.LISTENING,
                   voice_state.THINKING, voice_state.SPEAKING):
            voice_state.set_state(st)
            with open(voice_state.STATE_PATH) as f:
                seen.append(json.load(f)["state"])
        check("every transition is published",
              seen == ["idle", "listening", "thinking", "speaking"], str(seen))

        voice_state.set_state(voice_state.THINKING, command="what time is it")
        with open(voice_state.STATE_PATH) as f:
            payload = json.load(f)
        check("command text is carried", payload.get("last_command") == "what time is it")
        check("timestamp present for staleness detection", "updated_at" in payload)

        voice_state.clear()
        with open(voice_state.STATE_PATH) as f:
            check("clear() marks offline", json.load(f)["state"] == "offline")

        # Must never raise, whatever happens to the file.
        try:
            voice_state.set_state("idle")
            ok = True
        except Exception:
            ok = False
        check("publishing never raises", ok)
    finally:
        voice_state.set_state(original)


# ══════════════════════════════════════════════════════════════════════════
# FEATURE — conversation window (follow-ups without the wake word).
# ══════════════════════════════════════════════════════════════════════════

def test_conversation_window() -> None:
    section("FEATURE — conversation window")

    from voice.wake_word import WakeWordDetector

    d = WakeWordDetector()

    check("window configured", d._followup_window > 0, f"{d._followup_window}")
    check("closed at rest", not d._followup_active())

    # Arming must NOT open the window — it opens when TTS finishes, so a long
    # spoken reply cannot consume the time meant for the user's response.
    d.arm_followup()
    check("arming alone does not open the window",
          d._followup_armed and not d._followup_active())

    d._open_followup()
    check("opens once TTS finishes", d._followup_active() and not d._followup_armed)

    # Expiry
    d._followup_until = time.monotonic() - 1
    check("expires after the deadline", not d._followup_active())

    d._open_followup()
    d._close_followup("explicit wake")
    check("explicit wake word closes it", not d._followup_active())

    # Disabled configuration must never open a window.
    d._followup_window = 0.0
    d._followup_armed = False
    d.arm_followup()
    check("window of 0 disables the feature", not d._followup_armed)

    # Filler must not be treated as a command, but real one-word answers must.
    ignore = ["um", "uh", "hmm", "a", "the", "er", "mm", "x", ""]
    accept = ["no", "yes", "yeah", "sure", "ok", "hi", "stop", "next",
              "play music", "what time is it"]
    bad_ignore = [t for t in ignore if not WakeWordDetector._is_filler(t)]
    bad_accept = [t for t in accept if WakeWordDetector._is_filler(t)]
    check("disfluencies ignored", not bad_ignore, str(bad_ignore))
    check("short real answers accepted (incl. 'no')", not bad_accept, str(bad_accept))


# ══════════════════════════════════════════════════════════════════════════
# FEATURE — barge-in (interrupt mid-sentence without self-hearing).
# ══════════════════════════════════════════════════════════════════════════

def test_bargein() -> None:
    section("FEATURE — barge-in + echo rejection")

    from voice.echo_filter import is_echo, looks_like_interrupt
    from voice.wake_word import WakeWordDetector

    spoken = ("The weather in Chennai today is thirty two degrees and mostly "
              "sunny with a chance of rain later this evening.")

    # Jarvis hearing itself MUST be rejected — this is the feedback-loop guard.
    echoes = [
        "the weather in chennai today is thirty two degrees",
        "thirty two degrees and mostly sunny",
        "with a chance of rain later this evening",
        "mostly sunny with a chance of rain",
        "the weather in chennai",
    ]
    missed = [e for e in echoes if not is_echo(e, spoken)]
    check("self-hearing rejected", not missed, str(missed))

    # Real speech must get through.
    user = ["stop", "jarvis stop", "open spotify", "what about tomorrow",
            "no i meant delhi", "play some music instead", "cancel that"]
    blocked = [u for u in user if is_echo(u, spoken)]
    check("real barge-ins pass the filter", not blocked, str(blocked))

    check("no reference text means not echo", not is_echo("hello", None))
    check("empty transcription is never a barge-in", is_echo("", spoken))

    interrupts = ["stop", "shut up", "wait", "hold on", "enough", "cancel"]
    not_interrupts = ["open spotify", "hello", "what time is it"]
    check("stop phrases recognised",
          all(looks_like_interrupt(p) for p in interrupts))
    check("commands are not stop phrases",
          not any(looks_like_interrupt(p) for p in not_interrupts))

    d = WakeWordDetector()
    check("default mode is the conservative one", d._bargein_mode in ("wake", "off"),
          d._bargein_mode)

    # Runaway guard must disable itself rather than loop forever.
    d._bargein_mode = "any"
    d._bargein_times = []
    allowed = [d._note_bargein() for _ in range(6)]
    check("runaway guard disables barge-in", d._bargein_mode == "off",
          f"allowed={allowed}")


# ══════════════════════════════════════════════════════════════════════════
# FEATURE — pluggable speech engines (ElevenLabs + fallback).
# ══════════════════════════════════════════════════════════════════════════

def test_speech_engines() -> None:
    section("FEATURE — speech engines + fallback")

    from voice.speech_engines import (
        ElevenLabsEngine, FallbackEngine, MacSayEngine, SpeechEngine,
        build_engine,
    )

    mac = MacSayEngine("Samantha", 160)
    check("macOS say engine available", mac.available())

    # No key must mean unavailable, never a crash.
    check("ElevenLabs unavailable without a key",
          not ElevenLabsEngine(api_key="", voice_id="x").available())
    check("ElevenLabs unavailable without a voice id",
          not ElevenLabsEngine(api_key="k" * 32, voice_id="").available())

    # Cache keys must be stable and voice-specific, or switching voices would
    # replay the old one.
    e1 = ElevenLabsEngine("k" * 32, "voiceA", cache=False)
    e2 = ElevenLabsEngine("k" * 32, "voiceB", cache=False)
    check("cache key is stable for the same text",
          e1._cache_path("hello") == e1._cache_path("hello"))
    check("cache key differs per voice",
          e1._cache_path("hello") != e2._cache_path("hello"))
    check("cache key differs per text",
          e1._cache_path("hello") != e1._cache_path("goodbye"))

    # Fallback behaviour
    class Boom(SpeechEngine):
        name = "boom"
        def available(self): return True
        def speak(self, text, should_stop=None): return False
        def stop(self): pass

    class Records(SpeechEngine):
        name = "records"
        def __init__(self): self.spoken = []
        def available(self): return True
        def speak(self, text, should_stop=None):
            self.spoken.append(text); return True
        def stop(self): pass

    backup = Records()
    fb = FallbackEngine(primary=Boom(), backup=backup)
    fb.speak("hello")
    check("failure falls through to the backup engine",
          backup.spoken == ["hello"], str(backup.spoken))

    # A barge-in is not a failure — it must NOT re-speak via the backup.
    backup2 = Records()
    fb2 = FallbackEngine(primary=Boom(), backup=backup2)
    fb2.speak("interrupted", should_stop=lambda: True)
    check("interruption does not trigger fallback re-speak",
          backup2.spoken == [], str(backup2.spoken))

    # A working primary must be used and the backup left alone.
    good, unused = Records(), Records()
    fb3 = FallbackEngine(primary=good, backup=unused)
    fb3.speak("direct")
    check("working primary is used", good.spoken == ["direct"] and unused.spoken == [])

    # The factory must always return something usable.
    engine = build_engine()
    check("factory returns a usable engine", engine.available(), engine.name)


