# FEATURE — TTS still behaves after the engine refactor.
# ══════════════════════════════════════════════════════════════════════════

def test_tts_with_engine() -> None:
    section("FEATURE — TTS queue over a pluggable engine")

    from voice.speech_engines import SpeechEngine
    from voice.text_to_speech import TextToSpeech

    class Fake(SpeechEngine):
        name = "fake"
        def __init__(self):
            self.spoken = []
            self.stopped = 0
        def available(self): return True
        def speak(self, text, should_stop=None):
            if should_stop and should_stop():
                return False
            self.spoken.append(text)
            time.sleep(0.02)
            return True
        def stop(self): self.stopped += 1

    fake = Fake()
    tts = TextToSpeech(engine=fake)
    try:
        tts.speak("one")
        tts.speak("two")
        check("engine receives utterances in order",
              fake.spoken == ["one", "two"], str(fake.spoken))

        check("current_text is None when idle", tts.current_text() is None)

        tts.stop()
        check("stop() reaches the engine", fake.stopped >= 1)

        check("engine_name is exposed", tts.engine_name == "fake", tts.engine_name)
    finally:
        tts.shutdown()
    check("worker joins with a custom engine", not tts._worker.is_alive())


# ══════════════════════════════════════════════════════════════════════════
# BUG 8 — PCM byte misalignment produced static during neural TTS playback.
# ══════════════════════════════════════════════════════════════════════════

def test_pcm_alignment() -> None:
    section("BUG 8 — PCM sample alignment (audible static)")

    import math
    import struct

    from voice.speech_engines import SAMPLE_RATE, SILENCE_PAD

    # 16-bit PCM: every sample is exactly 2 bytes. The HTTP stream splits on
    # arbitrary boundaries — real measured sizes below, several odd. Writing an
    # odd-length buffer to a paInt16 device shifts every later sample by one
    # byte and is heard as static for the rest of the clip.
    samples = [int(8000 * math.sin(2 * math.pi * 440 * i / SAMPLE_RATE))
               for i in range(35840)]
    clean = b"".join(struct.pack("<h", v) for v in samples)

    sizes = [4096, 1183, 2403, 1211, 744, 1213, 2260, 1226]
    chunks, i = [], 0
    while i < len(clean):
        chunks.append(clean[i:i + sizes[len(chunks) % len(sizes)]])
        i += sizes[(len(chunks) - 1) % len(sizes)]

    check("test fixture actually contains odd-length chunks",
          any(len(c) % 2 for c in chunks))

    # Naive: write each chunk as it arrives.
    offset, naive_bad = 0, 0
    for c in chunks:
        if offset % 2:
            naive_bad += 1
        offset += len(c)
    check("naive playback misaligns samples (the bug)", naive_bad > 0,
          f"{naive_bad} misaligned writes")

    # Fixed: hold the trailing odd byte over to the next chunk.
    offset, fixed_bad, carry, out = 0, 0, b"", bytearray()
    for c in chunks:
        buf = carry + c
        carry = b""
        if len(buf) % 2:
            carry = buf[-1:]
            buf = buf[:-1]
        if offset % 2:
            fixed_bad += 1
        offset += len(buf)
        out.extend(buf)
    if carry:
        out.extend(carry + b"\x00")

    check("carry-byte buffering keeps every write sample-aligned",
          fixed_bad == 0, f"{fixed_bad} misaligned writes")
    check("no audio is lost or altered", bytes(out)[:len(clean)] == clean)
    check("output length stays even", len(out) % 2 == 0, str(len(out)))

    # The end-of-clip silence pad must itself be whole samples.
    check("silence pad is sample-aligned", len(SILENCE_PAD) % 2 == 0,
          str(len(SILENCE_PAD)))
    check("silence pad is silent", set(SILENCE_PAD) == {0})


