# BUG 9 — Irreversible actions executed on a single transcription.
# ══════════════════════════════════════════════════════════════════════════

def test_confirmation_gate() -> None:
    section("BUG 9 — Confirmation gate for irreversible actions")

    import asyncio

    from core.confirmation import ConfirmationGate, PendingAction, classify_reply
    from skills._registry import get_registry

    cases = [("yes", True), ("yeah", True), ("go ahead", True), ("do it", True),
             ("no", False), ("cancel", False), ("never mind", False),
             ("yeah no", False), ("yes but wait", False),
             ("what time is it", None), ("open spotify", None)]
    wrong = [t for t, want in cases if classify_reply(t) is not want]
    check("yes/no/neither classified correctly", not wrong, str(wrong))

    # A long sentence starting with "yes" is a command, not blanket approval.
    check("long 'yes ...' is not treated as approval",
          classify_reply("yes and also open chrome and play some music") is None)

    registry = get_registry()

    async def routes_gated(name: str, utterance: str) -> bool:
        skill = registry.by_name(name)
        if skill is None:
            return False
        m = skill.match(utterance)
        result = await skill.run(utterance, m.entities if m else {})
        return result.confirm is not None

    gated = {
        "shutdown_system": "shut down the mac",
        "restart_system": "restart the mac",
        "empty_trash": "empty the trash",
    }
    ungated = {"time_date": "what time is it", "jokes": "tell me a joke"}

    missing = [n for n, u in gated.items() if not asyncio.run(routes_gated(n, u))]
    check("every irreversible skill requires confirmation", not missing, str(missing))

    over = [n for n, u in ungated.items() if asyncio.run(routes_gated(n, u))]
    check("harmless skills are not gated", not over, str(over))

    # The gate must be single-use and time-limited.
    gate = ConfirmationGate(timeout=0.3)
    ran = []

    async def action() -> str:
        ran.append(1)
        return "done"

    gate.arm(PendingAction(description="test", run=action))
    check("action is pending after arming", gate.pending is not None)
    check("take() returns it", gate.take() is not None)
    check("take() clears it (single use)", gate.pending is None)

    gate.arm(PendingAction(description="test", run=action))
    time.sleep(0.4)
    check("pending action expires", gate.pending is None)
    check("expired action never ran", not ran)


