# FEATURE — pluggable STT with offline fallback.
# ══════════════════════════════════════════════════════════════════════════

def test_stt_chain() -> None:
    section("FEATURE — STT chain + failover")

    import speech_recognition as sr

    from voice.audio_utils import create_recognizer
    from voice.stt_engines import (
        ChainedSTT, GoogleEngine, GroqWhisperEngine, LocalWhisperEngine,
        STTEngine, build_stt,
    )

    check("Groq STT needs a key", not GroqWhisperEngine("").available())
    check("Groq STT available with a key", GroqWhisperEngine("k" * 20).available())

    chain = build_stt(create_recognizer())
    check("chain assembles at least one engine", chain.available(),
          str([e.name for e in chain.engines]))
    check("local Whisper is always in the chain (offline safety net)",
          any(e.name == "whisper" for e in chain.engines),
          str([e.name for e in chain.engines]))

    # An explicit offline preference must not be silently overridden just
    # because a faster network backend is configured.
    from config import settings
    if getattr(settings, "USE_OFFLINE_STT", False):
        check("USE_OFFLINE_STT keeps local first",
              chain.engines[0].name == "whisper", chain.engines[0].name)

    # Failover: a dead primary must not lose the utterance.
    class Dead(STTEngine):
        name = "dead"
        def available(self): return True
        def transcribe(self, audio): return None

    class Works(STTEngine):
        name = "works"
        def available(self): return True
        def transcribe(self, audio): return "hello world"

    fb = ChainedSTT([Dead(), Works()])
    silent = sr.AudioData(b"\x00" * 3200, 16000, 2)
    check("failover reaches a working engine", fb.transcribe(silent) == "hello world")
    check("last_used reports the engine that answered", fb.last_used == "works",
          fb.last_used)

    check("all-dead chain returns None, never raises",
          ChainedSTT([Dead(), Dead()]).transcribe(silent) is None)

    # Unavailable engines must be filtered out at construction.
    class Unavailable(STTEngine):
        name = "nope"
        def available(self): return False
        def transcribe(self, audio): return "should never run"

    filtered = ChainedSTT([Unavailable(), Works()])
    check("unavailable engines excluded",
          [e.name for e in filtered.engines] == ["works"],
          str([e.name for e in filtered.engines]))


