# FEATURE — searchable long-term context (aged-out turns).
# ══════════════════════════════════════════════════════════════════════════

def test_searchable_memory() -> None:
    section("FEATURE — retrieval of aged-out conversation turns")

    from memory.store import MemoryStore

    db = tempfile.mktemp(suffix=".db")
    m = MemoryStore(db)
    try:
        m.log_event("remind me the deadline is friday the 12th", "Noted.",
                    "remember", source="regex", confidence=0.9)
        m.log_event("what is my locker code", "Your locker code is 4471.",
                    "recall", source="regex", confidence=0.9)
        # Push those well outside any sliding window.
        for i in range(40):
            m.log_event(f"filler {i}", f"reply {i}", "jokes",
                        source="regex", confidence=0.9)

        hits = m.search_events("what was the deadline again")
        check("finds an aged-out turn by meaning",
              any("deadline" in u for u, _ in hits), str(hits[:1]))

        hits = m.search_events("remind me my locker code")
        check("retrieves the stored answer, not just the question",
              any("4471" in (r or "") for _, r in hits), str(hits[:1]))

        check("unrelated query retrieves nothing",
              not m.search_events("photosynthesis in tropical plants"))

        # A query of only stopwords carries no signal; matching arbitrary rows
        # would inject irrelevant "earlier context" into the prompt.
        for junk in ["what about the", "how are you", "and the that"]:
            check(f"stopword-only query returns nothing: {junk!r}",
                  not m.search_events(junk))

        # Ranking: more matching terms should win.
        m.log_event("the deadline for the report is friday", "ok", "remember",
                    source="regex", confidence=0.9)
        ranked = m.search_events("deadline report friday")
        check("more matching terms rank higher",
              ranked and "report" in ranked[0][0], str(ranked[:1]))
    finally:
        m.close()
        if os.path.exists(db):
            os.unlink(db)

    # The engine must degrade quietly if retrieval is unavailable.
    from ai.conversation_engine import ConversationEngine
    check("engine exposes retrieval helper",
          hasattr(ConversationEngine, "_recall_relevant"))
    check("engine derives its own query",
          hasattr(ConversationEngine, "_last_user_message"))


