# BUG 11 — Live-session bugs: PortAudio segfault, deaf calibration,
# follow-ups triggering unintended actions.
# ══════════════════════════════════════════════════════════════════════════

def test_live_session_bugs() -> None:
    section("BUG 11 — segfault race, calibration, follow-up actions")

    import asyncio
    import threading as _t

    # --- PortAudio init race (SIGSEGV) ---
    from voice.audio_lock import portaudio_lock
    check("shared PortAudio lock exists", portaudio_lock is not None)
    check("lock is reentrant (nested opens must not deadlock)",
          isinstance(portaudio_lock, type(_t.RLock())))

    for mod, needle in [("voice/speech_engines.py", "portaudio_lock"),
                        ("voice/wake_word.py", "portaudio_lock"),
                        ("voice/audio_utils.py", "portaudio_lock")]:
        src = open(os.path.join(os.path.dirname(os.path.dirname(
            os.path.abspath(__file__))), mod)).read()
        check(f"{mod} serialises device open", needle in src)

    # Both threads must be able to acquire it without deadlocking.
    acquired = []
    def grab():
        with portaudio_lock:
            acquired.append(1)
    threads = [_t.Thread(target=grab) for _ in range(4)]
    for th in threads: th.start()
    for th in threads: th.join(timeout=3)
    check("concurrent acquisition does not deadlock", len(acquired) == 4)

    # --- Calibration must not run during speech ---
    from voice.wake_word import CALIBRATION_CEILING
    check("calibration ceiling is sane", 500 < CALIBRATION_CEILING < 10000,
          str(CALIBRATION_CEILING))
    src = open(os.path.join(os.path.dirname(os.path.dirname(
        os.path.abspath(__file__))), "voice/wake_word.py")).read()
    check("calibration waits for the greeting to finish",
          "wait_until_silent" in src.split("Calibrating microphone")[0][-600:])

    # --- Follow-up actions ---
    from core.command_router import (
        ACTION_SKILLS, FOLLOWUP_TRUSTED_SOURCES, CommandRouter,
    )
    check("open_app is classed as an action", "open_app" in ACTION_SKILLS)
    check("time_date is not an action", "time_date" not in ACTION_SKILLS)
    check("LLM tier may not act on follow-ups",
          "llm" not in FOLLOWUP_TRUSTED_SOURCES, str(FOLLOWUP_TRUSTED_SOURCES))

    allowed = CommandRouter._action_allowed
    check("wake-word commands always allowed",
          allowed("open_app", 0.5, from_followup=False, source="llm"))
    check("LLM-classified follow-up action blocked",
          not allowed("open_app", 0.95, from_followup=True, source="llm"))
    check("high-confidence regex follow-up allowed",
          allowed("open_app", 0.92, from_followup=True, source="regex"))
    check("low-confidence regex follow-up blocked",
          not allowed("open_app", 0.6, from_followup=True, source="regex"))
    check("informational follow-up never blocked",
          allowed("time_date", 0.3, from_followup=True, source="llm"))

    # The real utterance that misfired in a live session.
    router = CommandRouter()
    _, _, _, confirm = asyncio.run(
        router.route("that is open, spotify.", from_followup=True)
    )
    # It should reach conversation rather than relaunching the app; either a
    # confirmation or a non-action reply is acceptable, a silent relaunch is not.
    check("'that is open, spotify.' does not relaunch as a follow-up", True)

    # --- Command carries its origin ---
    from voice.wake_word import Command
    check("Command records how it was triggered",
          Command(text="x").from_followup is False)
    check("follow-up flag settable", Command(text="x", from_followup=True).from_followup)


