# BUG 12 — Actions claimed success without observing the result.
# ══════════════════════════════════════════════════════════════════════════

def test_action_verification() -> None:
    section("BUG 12 — verify actions instead of assuming them")

    import asyncio

    from skills._registry import get_registry
    from skills.open_website import OpenWebsiteSkill

    registry = get_registry()

    # close_app announced "Flurbleglorp is closed." for an app that has never
    # existed — AppleScript does not error when told to quit a missing app.
    close = registry.by_name("close_app")
    m = close.match("close flurbleglorpxyz")
    result = asyncio.run(close.run("close flurbleglorpxyz", m.entities if m else {}))
    check("does not claim to close an app that was not running",
          "closed" not in result.text.lower() or "wasn't running" in result.text.lower(),
          result.text)
    check("says plainly that it was not running",
          "wasn't running" in result.text.lower(), result.text)

    # open_website used the raw utterance as the URL, producing
    # "https://open flurbleglorpsite" — a URL containing a space.
    clean = OpenWebsiteSkill._clean_target
    check("strips the leading verb", clean("open youtube") == "youtube",
          clean("open youtube"))
    check("strips multi-word verbs", clean("take me to github") == "github",
          clean("take me to github"))
    check("strips trailing filler",
          clean("visit reddit please") == "reddit", clean("visit reddit please"))

    plausible = OpenWebsiteSkill._PLAUSIBLE
    check("a hostname with a space is rejected",
          not plausible.match("stack overflow"))
    check("a normal hostname is accepted", bool(plausible.match("github.com")))

    site = registry.by_name("open_website")

    async def reply(utterance: str) -> str:
        mm = site.match(utterance)
        r = await site.run(utterance, mm.entities if mm else {})
        return r.text.lower()

    # Spoken multi-word site names should still work...
    for utterance, expected in [("take me to stack overflow", "stackoverflow"),
                                ("open hacker news", "hackernews")]:
        check(f"spoken site name resolves: {utterance!r}",
              expected in asyncio.run(reply(utterance)),
              asyncio.run(reply(utterance)))

    # ...but arbitrary sentences must NOT be mangled into a domain. An
    # unbounded version of that heuristic turned "the thing that i was
    # talking about yesterday" into a hostname and opened it.
    junk = asyncio.run(reply("open the thing that i was talking about yesterday"))
    check("a long sentence is not turned into a domain",
          "doesn't look like" in junk, junk[:70])

    # open_url reported success whenever the subprocess merely launched.
    import inspect
    from automation import browser_control
    src = inspect.getsource(browser_control.open_url)
    check("open_url checks the process return code", "returncode" in src)


# ══════════════════════════════════════════════════════════════════════════
# BUG 13 — Audio device change killed the neural voice permanently.
# ══════════════════════════════════════════════════════════════════════════

def test_audio_device_recovery() -> None:
    section("BUG 13 — recover from output-device changes")

    import inspect

    from config import settings
    from voice.speech_engines import ElevenLabsEngine

    src = inspect.getsource(ElevenLabsEngine._open_stream)
    check("_open_stream retries after a device error", "_retry" in src)
    check("stale PyAudio instance is torn down", "terminate()" in src)

    if not settings.ELEVENLABS_API_KEY:
        check("live device recovery (skipped: no API key)", True)
    else:
        engine = ElevenLabsEngine(
            settings.ELEVENLABS_API_KEY, settings.ELEVENLABS_VOICE_ID, cache=False
        )
        try:
            stream = engine._open_stream()
            check("output stream opens", stream is not None)
            engine._close_stream()

            # Reproduce the real failure: PortAudio enumerates devices once,
            # so a Bluetooth speaker connecting or dropping invalidates the
            # cached instance and every later open returns
            # [Errno -9996] Invalid output device.
            from voice.audio_lock import portaudio_lock
            with portaudio_lock:
                engine._audio.terminate()

            recovered = engine._open_stream()
            check("recovers after the device list goes stale", recovered is not None)
            engine._close_stream()
        finally:
            engine.shutdown()

    # Ctrl+C printed a traceback because the signal handler raised SystemExit
    # while the interpreter was already joining worker threads.
    import ast as _ast

    from core.assistant import JarvisAssistant

    handler_src = inspect.getsource(JarvisAssistant._setup_signal_handlers)

    # Parse for an actual call rather than string-matching: the first version
    # of this test searched for "sys.exit" and failed on the COMMENT
    # explaining why sys.exit is not used. Testing source text instead of
    # behaviour gives false failures.
    import textwrap as _tw
    tree = _ast.parse(_tw.dedent(handler_src))
    calls = [
        n for n in _ast.walk(tree)
        if isinstance(n, _ast.Call)
        and isinstance(n.func, _ast.Attribute)
        and n.func.attr == "exit"
    ]
    check("signal handler makes no exit() call", not calls, f"{len(calls)} found")
    check("signal handler still stops the loop", "_running = False" in handler_src)

    # And the teardown must still run when the loop exits normally.
    start_src = inspect.getsource(JarvisAssistant.start)
    check("start() guarantees shutdown via finally",
          "finally" in start_src and "_shutdown()" in start_src)
    check("shutdown is idempotent",
          "_shutdown_done" in inspect.getsource(JarvisAssistant._shutdown))


# ══════════════════════════════════════════════════════════════════════════
# BUG 14 — Words lost between the wake frame and the command frame.
# ══════════════════════════════════════════════════════════════════════════

def test_wake_frame_timing() -> None:
    section("BUG 14 — audio lost in the transcription gap")

    from utils.helpers import contains_wake_word, strip_wake_word
    from voice.wake_word import (
        COMMAND_PAUSE_THRESHOLD, WAKE_PAUSE_THRESHOLD, WAKE_PHRASE_LIMIT_SEC,
        WakeWordDetector,
    )

    # The idle listen must tolerate a longer pause than the command capture:
    # that pause is exactly where "jarvis <pause> play something" was being
    # split, losing the words spoken while the wake frame was transcribed.
    check("wake listen tolerates a longer pause",
          WAKE_PAUSE_THRESHOLD > COMMAND_PAUSE_THRESHOLD,
          f"wake={WAKE_PAUSE_THRESHOLD} command={COMMAND_PAUSE_THRESHOLD}")
    check("wake pause is long enough to bridge a natural pause",
          WAKE_PAUSE_THRESHOLD >= 0.6, str(WAKE_PAUSE_THRESHOLD))
    check("but not so long that replies feel sluggish",
          WAKE_PAUSE_THRESHOLD <= 1.2, str(WAKE_PAUSE_THRESHOLD))
    check("command capture stays fast",
          COMMAND_PAUSE_THRESHOLD <= 0.5, str(COMMAND_PAUSE_THRESHOLD))
    check("wake frame is long enough for wake word plus a command",
          WAKE_PHRASE_LIMIT_SEC >= 6, str(WAKE_PHRASE_LIMIT_SEC))

    # The threshold must be restored, or the command capture would inherit
    # the slow setting and every reply would lag.
    d = WakeWordDetector()
    baseline = d.recognizer.pause_threshold
    with d._pause_threshold(WAKE_PAUSE_THRESHOLD):
        inside = d.recognizer.pause_threshold
    check("threshold applies inside the context", inside == WAKE_PAUSE_THRESHOLD)
    check("threshold is restored afterwards",
          d.recognizer.pause_threshold == baseline)

    # Restored even if the listen raises.
    try:
        with d._pause_threshold(WAKE_PAUSE_THRESHOLD):
            raise RuntimeError("simulated listen failure")
    except RuntimeError:
        pass
    check("threshold restored after an exception",
          d.recognizer.pause_threshold == baseline)

    # The whole utterance in one frame is the path that avoids the gap.
    for utterance, expected in [
        ("jarvis play something on spotify", "play something on spotify"),
        ("javis open chrome", "open chrome"),
        ("hey jarvis what time is it", "what time is it"),
    ]:
        check(f"single-frame utterance yields the command: {utterance!r}",
              contains_wake_word(utterance)
              and strip_wake_word(utterance) == expected,
              strip_wake_word(utterance))


