# BUG 15 — Two Jarvis instances could run at once.
# ══════════════════════════════════════════════════════════════════════════

def test_single_instance() -> None:
    section("BUG 15 — single-instance lock")

    import subprocess as _sp
    import sys as _sys

    from core.single_instance import (
        LOCK_PATH, AlreadyRunning, acquire, read_lock, release,
    )

    release()
    check("lock is free to begin with", read_lock() is None)

    acquire()
    check("lock file is written", LOCK_PATH.exists())
    check("our own pid does not block us", read_lock() is None)

    # Another process must see the lock and be refused. A live PID means a
    # live Jarvis: two of them fight over the microphone and both speak,
    # which is what made Jarvis appear to talk after being shut down.
    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    out = _sp.run(
        [_sys.executable, "-c",
         "import sys; sys.path.insert(0, '.'); "
         "from core.single_instance import read_lock; print(read_lock())"],
        capture_output=True, text=True, cwd=root, timeout=30,
    )
    seen = out.stdout.strip()
    check("another process sees the live lock",
          seen == str(os.getpid()), f"saw {seen!r}")

    release()
    check("release frees the lock", read_lock() is None)
    check("lock file removed", not LOCK_PATH.exists())

    # A crash leaves a PID file behind with no process. That must be
    # reclaimed, not treated as a permanent block on ever starting again.
    LOCK_PATH.parent.mkdir(parents=True, exist_ok=True)
    LOCK_PATH.write_text("999999")     # a pid that cannot be running
    check("stale lock from a dead pid is reclaimed", read_lock() is None)
    check("stale lock file is cleaned up", not LOCK_PATH.exists())

    # A garbage file must not wedge startup either.
    LOCK_PATH.write_text("not-a-pid")
    check("unparseable lock file is ignored", read_lock() is None)
    release()
    if LOCK_PATH.exists():
        LOCK_PATH.unlink()

    # run.py must actually use the guard, and stop.py must exist.
    run_src = open(os.path.join(root, "run.py")).read()
    check("run.py acquires the lock", "acquire()" in run_src)
    check("run.py releases it on exit", "release()" in run_src)
    check("run.py exits when already running", "AlreadyRunning" in run_src)

    stop_path = os.path.join(root, "stop.py")
    check("stop.py exists", os.path.exists(stop_path))
    if os.path.exists(stop_path):
        stop_src = open(stop_path).read()
        # The system voice is its own process and outlives the assistant.
        check("stop.py also kills orphaned speech", "say" in stop_src)


def main() -> int:
    print("=" * 68)
    print("JARVIS REGRESSION SUITE".center(68))
    print("=" * 68)

    for fn in (test_tts_concurrency, test_memory_store, test_wake_word,
               test_applescript, test_routing, test_imports,
               test_local_intent_model, test_feedback_loop, test_voice_state,
               test_conversation_window, test_bargein,
               test_speech_engines, test_tts_with_engine, test_pcm_alignment,
               test_confirmation_gate, test_llm_and_speech_hygiene,
               test_stt_chain, test_searchable_memory, test_live_session_bugs,
               test_action_verification, test_audio_device_recovery,
               test_wake_frame_timing, test_single_instance):
        try:
            fn()
        except Exception as e:
            import traceback
            check(f"{fn.__name__} raised", False, traceback.format_exc(limit=3))

    print("\n" + "=" * 68)
    total = len(PASS) + len(FAIL)
    print(f"  {len(PASS)}/{total} passed")
    if FAIL:
        print("  FAILED:")
        for f in FAIL:
            print(f"    - {f}")
    print("=" * 68)
    return 1 if FAIL else 0


if __name__ == "__main__":
    sys.exit(main())
